import 'package:flutter/material.dart';
import '../../services/api_service.dart';
class AttendanceScreen extends StatefulWidget{const AttendanceScreen({super.key});@override State<AttendanceScreen> createState()=>_AttendanceScreenState();}
class _AttendanceScreenState extends State<AttendanceScreen>{List attendance=[],students=[],teachers=[];bool loading=true;String? error;List<dynamic> list(dynamic x){if(x is List)return List<dynamic>.from(x);if(x is Map){final d=x['data'];if(d is List)return List<dynamic>.from(d);if(d is Map&&d['data'] is List)return List<dynamic>.from(d['data']);}return[];}int id(dynamic x)=>int.tryParse('${x['id']}')??0;void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));@override void initState(){super.initState();load();}
Future<void> load()async{if(mounted)setState(()=>loading=true);Object? primary;try{final r=await ApiService.get('attendance');if(mounted)setState(()=>attendance=list(r));}catch(e){primary=e;}try{final r=await ApiService.get('students');if(mounted)setState(()=>students=list(r));}catch(_){ }try{final r=await ApiService.get('teachers');if(mounted)setState(()=>teachers=list(r));}catch(_){ }if(mounted){setState((){loading=false;error=primary?.toString();});}}
Future<void> add()async{if(students.isEmpty){msg('أضف طالبًا أولًا');return;}int studentId=id(students.first);int? teacherId=teachers.isEmpty?null:id(teachers.first);String status='present';final date=TextEditingController(text:DateTime.now().toIso8601String().substring(0,10)),notes=TextEditingController();final k=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(d)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('تسجيل حضور'),content:Form(key:k,child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<int>(value:studentId,items:students.map((x)=>DropdownMenuItem(value:id(x),child:Text('${x['name']??''}'))).toList(),onChanged:(v){if(v!=null)set(()=>studentId=v);}),if(teachers.isNotEmpty)DropdownButtonFormField<int>(value:teacherId,items:teachers.map((x)=>DropdownMenuItem(value:id(x),child:Text('${x['name']??''}'))).toList(),onChanged:(v)=>set(()=>teacherId=v)),DropdownButtonFormField<String>(value:status,items:const[DropdownMenuItem(value:'present',child:Text('حاضر')),DropdownMenuItem(value:'absent',child:Text('غائب')),DropdownMenuItem(value:'late',child:Text('متأخر')),DropdownMenuItem(value:'excused',child:Text('معتذر'))],onChanged:(v){if(v!=null)set(()=>status=v);}),TextFormField(controller:date,decoration:const InputDecoration(labelText:'التاريخ YYYY-MM-DD'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),TextFormField(controller:notes,decoration:const InputDecoration(labelText:'ملاحظات'))])),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(k.currentState!.validate())Navigator.pop(d,true);},child:const Text('حفظ'))])));if(ok==true){try{await ApiService.post('attendance',{'student_id':studentId,'teacher_id':teacherId,'date':date.text.trim(),'status':status,'notes':notes.text.trim()});await load();msg('تم تسجيل الحضور');}catch(e){msg(e);}}date.dispose();notes.dispose();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('الحضور'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton(onPressed:add,child:const Icon(Icons.add)),body:loading?const Center(child:CircularProgressIndicator()):error!=null?Center(child:Text(error!)):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:attendance.length,itemBuilder:(_,i){final x=attendance[i],s=x['student'],st='${x['status']??''}';final label=st=='present'?'حاضر':st=='late'?'متأخر':st=='excused'?'معتذر':'غائب';return Card(child:ListTile(title:Text(s is Map?'${s['name']??'طالب'}':'طالب'),subtitle:Text('${x['date']??''}'),trailing:Text(label)));}));}
